-- Deterministic phone catalog seed.
--
-- Idempotent: re-running this file updates the same rows and never creates
-- duplicates. Run it after all migrations with `make seed`.

BEGIN;

-- Keep the original catalog rows for rollback compatibility, but hide them
-- from the phone catalog.
UPDATE products
SET active = false
WHERE id IN (
    '00000000-0000-0001-0000-000000000001',
    '00000000-0000-0001-0000-000000000002',
    '00000000-0000-0001-0000-000000000003',
    '00000000-0000-0001-0000-000000000004',
    '00000000-0000-0001-0000-000000000005',
    '00000000-0000-0001-0000-000000000006',
    '00000000-0000-0001-0000-000000000007',
    '00000000-0000-0001-0000-000000000008',
    '00000000-0000-0001-0000-000000000009'
);

-- Delete all child variant option values first to satisfy foreign keys
DELETE FROM variant_option_values
WHERE product_id IN (SELECT id FROM products WHERE id::text LIKE '10000000-%');

DELETE FROM product_variants
WHERE product_id IN (SELECT id FROM products WHERE id::text LIKE '10000000-%')
  AND NOT EXISTS (
      SELECT 1 FROM cart_items WHERE cart_items.variant_id = product_variants.id
  );

DELETE FROM product_option_values
WHERE product_id IN (SELECT id FROM products WHERE id::text LIKE '10000000-%');

DELETE FROM product_option_groups
WHERE product_id IN (SELECT id FROM products WHERE id::text LIKE '10000000-%');

DELETE FROM product_images
WHERE id::text LIKE '10000000-0000-0002-%';

ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name;

ON CONFLICT (id) DO UPDATE SET
    category_id = EXCLUDED.category_id,
    name = EXCLUDED.name,
    model = EXCLUDED.model,
    brand = EXCLUDED.brand,
    description = EXCLUDED.description,
    price = EXCLUDED.price,
    currency = EXCLUDED.currency,
    stock_quantity = EXCLUDED.stock_quantity,
    featured = EXCLUDED.featured,
    active = EXCLUDED.active;

ON CONFLICT (id) DO UPDATE SET
    product_id = EXCLUDED.product_id,
    url = EXCLUDED.url,
    position = EXCLUDED.position;

ON CONFLICT (id) DO UPDATE SET label = EXCLUDED.label, position = EXCLUDED.position;

ON CONFLICT (id) DO UPDATE SET label = EXCLUDED.label, position = EXCLUDED.position;

ON CONFLICT (id) DO UPDATE SET
    product_id = EXCLUDED.product_id,
    price_vnd = EXCLUDED.price_vnd,
    stock_quantity = EXCLUDED.stock_quantity,
    active = EXCLUDED.active,
    updated_at = now();

ON CONFLICT (variant_id, group_id) DO UPDATE SET
    option_value_id = EXCLUDED.option_value_id;

UPDATE products SET price = 28990000, stock_quantity = 136 WHERE id = '10000000-0000-0001-0000-000000000001';
UPDATE products SET price = 16990000, stock_quantity = 62 WHERE id = '10000000-0000-0001-0000-000000000002';
UPDATE products SET price = 20990000, stock_quantity = 62 WHERE id = '10000000-0000-0001-0000-000000000003';
UPDATE products SET price = 4990000, stock_quantity = 62 WHERE id = '10000000-0000-0001-0000-000000000004';
UPDATE products SET price = 36990000, stock_quantity = 62 WHERE id = '10000000-0000-0001-0000-000000000005';
UPDATE products SET price = 22990000, stock_quantity = 62 WHERE id = '10000000-0000-0001-0000-000000000006';
UPDATE products SET price = 31490000, stock_quantity = 62 WHERE id = '10000000-0000-0001-0000-000000000007';
UPDATE products SET price = 18990000, stock_quantity = 62 WHERE id = '10000000-0000-0001-0000-000000000008';
UPDATE products SET price = 13490000, stock_quantity = 17 WHERE id = '10000000-0000-0001-0000-000000000009';
UPDATE products SET price = 35990000, stock_quantity = 62 WHERE id = '10000000-0000-0001-0000-000000000010';
UPDATE products SET price = 21990000, stock_quantity = 62 WHERE id = '10000000-0000-0001-0000-000000000011';
UPDATE products SET price = 43990000, stock_quantity = 62 WHERE id = '10000000-0000-0001-0000-000000000012';
UPDATE products SET price = 26990000, stock_quantity = 62 WHERE id = '10000000-0000-0001-0000-000000000013';
UPDATE products SET price = 9690000, stock_quantity = 62 WHERE id = '10000000-0000-0001-0000-000000000014';
UPDATE products SET price = 4490000, stock_quantity = 17 WHERE id = '10000000-0000-0001-0000-000000000015';
UPDATE products SET price = 34990000, stock_quantity = 62 WHERE id = '10000000-0000-0001-0000-000000000016';
UPDATE products SET price = 17990000, stock_quantity = 62 WHERE id = '10000000-0000-0001-0000-000000000017';
UPDATE products SET price = 10990000, stock_quantity = 62 WHERE id = '10000000-0000-0001-0000-000000000018';
UPDATE products SET price = 9890000, stock_quantity = 62 WHERE id = '10000000-0000-0001-0000-000000000019';
UPDATE products SET price = 3190000, stock_quantity = 17 WHERE id = '10000000-0000-0001-0000-000000000020';
COMMIT;
